import{_ as s,C as n,o as e,c as h,j as i,E as l,a as o,a2 as t}from"./chunks/framework.C21TwvGF.js";const D=JSON.parse(`{"title":"5-dars (Mentor). Photoshop interfeysi va vositalari (1-qism): 2D grafika turlari va interfeys","description":"","frontmatter":{"title":"5-dars (Mentor). Photoshop interfeysi va vositalari (1-qism): 2D grafika turlari va interfeys","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_dars","dars":{"sinf":{"name":"9-sinf (Game)","link":"/mentor/9-sinf-game/"},"week":{"n":2,"link":"/mentor/9-sinf-game/hafta-02/"},"g":5,"title":"Photoshop interfeysi va vositalari (1-qism): 2D grafika turlari va interfeys","lead":"2D o'yin san'ati — bu har bir piksel va chiziq orqali virtual dunyoni jonlantirish, o'yinchiga estetik zavq va unutilmas vizual muhit ulashish mahoratidir!","slide":"/slaydlar/9-sinf-game/hafta-02/dars-2.html","test":"/slaydlar/9-sinf-game/hafta-02/dars-2-test.html","student_link":"/9-sinf-game/hafta-02/dars-2","tabs":[{"g":4,"link":"/mentor/9-sinf-game/hafta-02/dars-1","current":false},{"g":5,"link":"/mentor/9-sinf-game/hafta-02/dars-2","current":true},{"g":6,"link":"/mentor/9-sinf-game/hafta-02/dars-3","current":false}],"prev":{"g":4,"title":"O‘yin loyihalash va ssenariy: G'oyadan voqealar zanjirigacha","link":"/mentor/9-sinf-game/hafta-02/dars-1"},"next":{"g":6,"title":"Photoshop interfeysi va vositalari (2-qism): Tanlash vositalari, qatlamlar va uskunalar","link":"/mentor/9-sinf-game/hafta-02/dars-3"}}},"headers":[],"relativePath":"mentor/9-sinf-game/hafta-02/dars-2.md","filePath":"mentor/9-sinf-game/hafta-02/dars-2.md"}`),d={name:"mentor/9-sinf-game/hafta-02/dars-2.md"},m={class:"blk"},k={id:"dars-rejasi",tabindex:"-1"},g={class:"blk"},u={id:"mentor-konspekti",tabindex:"-1"},y={class:"blk"},f={id:"amaliy-topshiriqlar-va-yechimlar",tabindex:"-1"},q={class:"blk"},b={id:"tezkor-nazorat-savollari",tabindex:"-1"},p={class:"blk"},v={id:"uyga-vazifa",tabindex:"-1"};function c(_,a,P,z,x,T){const r=n("Icon");return e(),h("div",null,[i("div",m,[i("h2",k,[l(r,{name:"file-text"}),a[0]||(a[0]=o(" Dars rejasi ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#dars-rejasi","aria-label":'Permalink to "<Icon name="file-text" /> Dars rejasi"'},"​",-1))]),a[2]||(a[2]=t("<ul><li><strong>Darsning maqsadi:</strong> O&#39;quvchilarga II bob: 2D grafika asoslari bo&#39;yicha kirish bilimlarini berish, 2D grafikaning o&#39;yindagi asosiy elementlari (spraytlar, tayllar, fonlar, UI elementlari), kompyuter grafikasining 3 ta asosiy turi (Rastr, Vektor, Fraktal) hamda Adobe Photoshop dasturining interfeysi, asosiy panellari (Canvas, Tools, Options Bar, Layers) va ishchi muhit sozlamalarini o&#39;rgatish.</li><li><strong>Kutiladigan natija:</strong> O&#39;quvchilar rastr va vektor grafikasining farqini amalda ko&#39;ra oladi; o&#39;yinda sprayt va tayl xaritalari (Tilemaps) nima uchun kerakligini tushunadi; Adobe Photoshop interfeysida erkin harakatlanadi va o&#39;yin assetlari uchun to&#39;g&#39;ri o&#39;lchamdagi yangi fayl (Canvas) yarata oladi.</li><li><strong>Vaqt taqsimoti:</strong><ul><li>O&#39;tgan mavzuni takrorlash (Ssenariy va GDD): 10 daqiqa</li><li>Yangi mavzu: 2D grafika elementlari (Sprayt, Tayl, Fon): 20 daqiqa</li><li>Grafika turlari: Rastr, Vektor va Fraktal: 25 daqiqa</li><li>Adobe Photoshop interfeysi va amaliy tanishuv: 15 daqiqa</li><li>Nazorat savollari va dars xulosasi: 10 daqiqa</li></ul></li></ul><hr>",2))]),i("div",g,[i("h2",u,[l(r,{name:"file-text"}),a[3]||(a[3]=o(" Mentor konspekti ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#mentor-konspekti","aria-label":'Permalink to "<Icon name="file-text" /> Mentor konspekti"'},"​",-1))]),a[5]||(a[5]=t('<h3 id="_1-2d-grafika-va-uning-o-yindagi-asosiy-elementlari" tabindex="-1">1. 2D grafika va uning o&#39;yindagi asosiy elementlari <a class="header-anchor" href="#_1-2d-grafika-va-uning-o-yindagi-asosiy-elementlari" aria-label="Permalink to &quot;1. 2D grafika va uning o&#39;yindagi asosiy elementlari&quot;">​</a></h3><p>2D grafika (ikki o&#39;lchamli) — kenglik (X) va balandlik (Y) o&#39;qlari bo&#39;yicha tekislikda mavjud bo&#39;lgan tasvirlardir. O&#39;yin ishlab chiqishda 2D grafika 4 ta asosiy guruhga bo&#39;linadi:</p><ol><li><strong>Spraytlar (Sprites):</strong> O&#39;yindagi har qanday harakatlanuvchi yoki statik obyektlar tasviri (bosh qahramon, dushmanlar, tangalar, sandiqlar). Ular ko&#39;pincha alohida kadrlar ko&#39;rinishida chizilib, keyinchalik kadrma-kadr animatsiyaga birlashtiriladi.</li><li><strong>Tayllar (Tiles) va Tayl xaritalari (Tilemaps):</strong> Katta o&#39;yin darajalarini (xaritalarni) bloklardan mozaika kabi terish uchun ishlatiladigan kichik o&#39;lchamdagi takrorlanuvchi rasmlar (masalan, $32\\times32$ yoki $64\\times64$ pikselli yer, o&#39;t, g&#39;isht, suv bloklari). Ular xotirani bir necha o&#39;n barobar tejaydi.</li><li><strong>Fonlar (Backgrounds):</strong> O&#39;yin atmosferasini yaratuvchi orqa fon rasmlari. Ko&#39;pincha 3-4 xil qatlamdan iborat bo&#39;lib, <strong>Parallaks effekti</strong> (yaqin qatlam tez, uzoqdagi tog&#39;lar sekin harakatlanishi) orqali chuqurlik hosil qiladi.</li><li><strong>UI elementlari:</strong> Tugmalar, menyu ramkalari, yurakchalar va xarita foni.</li></ol><h3 id="_2-kompyuter-grafikasining-3-ta-asosiy-turi" tabindex="-1">2. Kompyuter grafikasining 3 ta asosiy turi <a class="header-anchor" href="#_2-kompyuter-grafikasining-3-ta-asosiy-turi" aria-label="Permalink to &quot;2. Kompyuter grafikasining 3 ta asosiy turi&quot;">​</a></h3><ol><li><strong>Rastr grafikasi (Raster):</strong><ul><li>Rangli nuqtalar — <strong>piksellar to&#39;ri (Matrix of Pixels)</strong> dan iborat.</li><li><em>Afzalligi:</em> Yuqori darajadagi fotorealistik sifat, ranglarning mayin o&#39;tishi va murakkab gradiyentlar.</li><li><em>Kamchiligi:</em> Kattalashtirilganda (zoom) sifat yo&#39;qoladi, piksellar ko&#39;rinib qoladi (pikselizatsiya); fayl hajmi kattaroq bo&#39;ladi.</li><li><em>Formatlar:</em> PNG (shaffof fonli spraytlar uchun), JPEG (fotosuratlar), PSD (Photoshop manba fayli), WebP.</li></ul></li><li><strong>Vektor grafikasi (Vector):</strong><ul><li>Piksellar emas, balki matematik formulalar va geometrik primitivlar (nuqtalar, to&#39;g&#39;ri va egri chiziqlar, ko&#39;pburchaklar) asosida quriladi.</li><li><em>Afzalligi:</em> Sifatni mutlaqo yo&#39;qotmasdan istalgancha kattalashtirish (cheksiz masshtablash); fayl hajmi juda kichik.</li><li><em>Kamchiligi:</em> Fotosurat sifatidagi murakkab rang o&#39;tishlarini yaratish qiyin.</li><li><em>Formatlar:</em> SVG, AI, EPS. O&#39;yinda logotiplar, piktogrammalar va shriftlar uchun ishlatiladi.</li></ul></li><li><strong>Fraktal grafikasi (Fractal):</strong><ul><li>Matematik o&#39;z-o&#39;ziga o&#39;xshashlik (self-similarity) formulalari asosida quriladi.</li><li>Tabiiy obyektlarni (bulutlar, olov, qor parchalari, tog&#39; tizmalari) procedural generatsiya qilishda qo&#39;llaniladi.</li></ul></li></ol><h3 id="_3-adobe-photoshop-interfeysi-arxitekturasi" tabindex="-1">3. Adobe Photoshop interfeysi arxitekturasi <a class="header-anchor" href="#_3-adobe-photoshop-interfeysi-arxitekturasi" aria-label="Permalink to &quot;3. Adobe Photoshop interfeysi arxitekturasi&quot;">​</a></h3><p>Photoshop — bu butun dunyo bo&#39;yicha 2D o&#39;yin san&#39;ati va to&#39;qimalarini yaratishda eng keng tarqalgan professional rastr muharriri. Interfeys 5 ta asosiy zonadan iborat:</p><ol><li><strong>Canvas (Ishchi xolst):</strong> Tasvir chiziladigan markaziy maydon. O&#39;yin uchun odatda $1920\\times1080$ (Full HD) yoki pikselli o&#39;yinlar uchun kichik o&#39;lchamlarda ochiladi (Resolution: 72 DPI ekranga, 300 DPI esa chop etishga).</li><li><strong>Tools Panel (Vositalar paneli — chapda):</strong> Chizish, kesish, bo&#39;yash va tanlash uskunalari (Move V, Brush B, Eraser E va h.k.).</li><li><strong>Options Bar (Xususiyatlar paneli — tepada):</strong> Tanlangan uskunaning maxsus parametrlarini (o&#39;lchami, shaffofligi, qattiqligi) sozlaydi.</li><li><strong>Layers Panel (Qatlamlar paneli — o&#39;ngda):</strong> Photoshopning eng muhim yuragi. Har bir personaj, fon yoki detal alohida qatlamda (Layer) turadi.</li><li><strong>Menu Bar (Asosiy menyu — eng tepada):</strong> File, Edit, Image, Layer, Filter kabi global amallar.</li></ol><hr>',9))]),i("div",y,[i("h2",f,[l(r,{name:"file-text"}),a[6]||(a[6]=o(" Amaliy topshiriqlar va yechimlar ",-1)),a[7]||(a[7]=i("a",{class:"header-anchor",href:"#amaliy-topshiriqlar-va-yechimlar","aria-label":'Permalink to "<Icon name="file-text" /> Amaliy topshiriqlar va yechimlar"'},"​",-1))]),a[8]||(a[8]=t('<h3 id="_1-topshiriq-rastr-va-vektor-farqini-amalda-aniqlash-oson" tabindex="-1">1-topshiriq. Rastr va vektor farqini amalda aniqlash (oson) <a class="header-anchor" href="#_1-topshiriq-rastr-va-vektor-farqini-amalda-aniqlash-oson" aria-label="Permalink to &quot;1-topshiriq. Rastr va vektor farqini amalda aniqlash (oson)&quot;">​</a></h3><p>Smartfon o&#39;yinining ekrandagi salomatlik yurakchasi ikonkasi va o&#39;yindagi o&#39;rmon foni rasmi berilgan. Qaysi biri vektor, qaysi biri rastr formatida bo&#39;lishi maqsadga muvofiq va nima uchun?</p><p><strong>Yechim:</strong></p><ul><li><strong>Salomatlik yurakchasi (UI ikonka) $\\to$ Vektor (SVG).</strong> Sababi: Turli o&#39;lchamdagi ekranlarda (kichik telefon yoki katta planshet) sifati zarracha buzilmasdan aniq ko&#39;rinishi kerak, fayl hajmi esa bir necha kilobayt bo&#39;ladi.</li><li><strong>O&#39;rmon foni $\\to$ Rastr (PNG/JPEG/PSD).</strong> Sababi: O&#39;rmonda millionlab rang tuslari, soyalar va mayin gradiyentlar mavjud bo&#39;lib, buni faqat piksellar to&#39;ri orqali ifodalash mumkin.</li></ul><h3 id="_2-topshiriq-o-yin-xaritasi-uchun-tayl-tile-hisob-kitobi-o-rta" tabindex="-1">2-topshiriq. O&#39;yin xaritasi uchun Tayl (Tile) hisob-kitobi (o&#39;rta) <a class="header-anchor" href="#_2-topshiriq-o-yin-xaritasi-uchun-tayl-tile-hisob-kitobi-o-rta" aria-label="Permalink to &quot;2-topshiriq. O&#39;yin xaritasi uchun Tayl (Tile) hisob-kitobi (o&#39;rta)&quot;">​</a></h3><p>O&#39;yin ekrani o&#39;lchami $1920\\times1080$ piksel. O&#39;yin darajasi esa $32\\times32$ pikselli standart kvadrat tayllardan tuzilishi kerak. Ekranni to&#39;liq qoplash uchun eniga va bo&#39;yiga nechtadan tayl kerak bo&#39;ladi? Tayllardan foydalanish bitta yaxlit ulkan rasmdan ko&#39;ra qanday texnik ustunlik beradi?</p><p><strong>Yechim:</strong></p><ol><li>Eniga tayllar soni: $1920 / 32 = 60$ ta tayl;</li><li>Bo&#39;yiga tayllar soni: $1080 / 32 = 33.75 \\approx 34$ ta tayl;</li><li>Jami ekranda: $60 \\times 34 = 2040$ ta tayl katakchasi mavjud. <em>Texnik ustunlik:</em> 2040 ta tayl uchun alohida 2040 ta rasm chizilmaydi! Bor-yo&#39;g&#39;i 5-10 ta unikal blok (o&#39;t, tosh, tuproq) chiziladi va o&#39;yin xotirasida (RAM) bir necha megabayt joy tejab qolinadi.</li></ol><h3 id="_3-topshiriq-photoshopda-o-yin-loyihasi-uchun-to-g-ri-canvas-ochish-qiyin" tabindex="-1">3-topshiriq. Photoshopda o&#39;yin loyihasi uchun to&#39;g&#39;ri Canvas ochish (qiyin) <a class="header-anchor" href="#_3-topshiriq-photoshopda-o-yin-loyihasi-uchun-to-g-ri-canvas-ochish-qiyin" aria-label="Permalink to &quot;3-topshiriq. Photoshopda o&#39;yin loyihasi uchun to&#39;g&#39;ri Canvas ochish (qiyin)&quot;">​</a></h3><p>Android smartfonlar uchun 2D o&#39;yin bosh menyusi dizaynini boshlamoqchisiz. Photoshop dasturida yangi fayl ochish (<code>Ctrl + N</code>) oynasida quyidagi parametrlarni qanday sozlashingiz kerakligini asoslang:</p><ol><li>Width va Height (Kenglik va bo&#39;ylik);</li><li>Resolution (Ajratish qobiliyati);</li><li>Color Mode (Rang modeli);</li><li>Background Contents.</li></ol><p><strong>Yechim:</strong></p><ol><li><strong>Width &amp; Height:</strong> <code>1920 x 1080 Pixels</code> (Landscape/Gorizontal) yoki <code>1080 x 1920 Pixels</code> (Portrait/Vertikal) — zamonaviy smartfonlarning eng keng tarqalgan Full HD standarti.</li><li><strong>Resolution:</strong> <code>72 Pixels/Inch</code> (yoki 150 PPI). Sababi: Ekranda ko&#39;rsatiladigan raqamli grafika uchun 72 DPI yetarli, ortiqcha 300 DPI qilish faqat fayl hajmini asossiz oshiradi.</li><li><strong>Color Mode:</strong> <code>RGB Color, 8 bit</code>. Sababi: Barcha elektron displeylar (ekranlar) qizil, yashil, ko&#39;k nurlar yig&#39;indisi (RGB) asosida ishlaydi (CMYK faqat bosmaxonaga kerak).</li><li><strong>Background Contents:</strong> <code>Transparent</code> (Shaffof). Sababi: Keyinchalik o&#39;yin dvijogiga o&#39;tkazilganda ortiqcha oq fon xalaqit bermasligi lozim.</li></ol><hr>',14))]),i("div",q,[i("h2",b,[l(r,{name:"file-text"}),a[9]||(a[9]=o(" Tezkor nazorat savollari ",-1)),a[10]||(a[10]=i("a",{class:"header-anchor",href:"#tezkor-nazorat-savollari","aria-label":'Permalink to "<Icon name="file-text" /> Tezkor nazorat savollari"'},"​",-1))]),a[11]||(a[11]=t("<ol><li>2D o&#39;yinlarda harakatlanuvchi personajlar va buyumlar rasmlari qanday ataladi? <ul><li><em>Javob:</em> Spraytlar (Sprites).</li></ul></li><li>Rastr grafikasining asosiy kamchiligi nima? <ul><li><em>Javob:</em> Tasvir kattalashtirilganda uning sifati yo&#39;qolishi va piksellashib qolishi.</li></ul></li><li>Shaffof fonni qo&#39;llab-quvvatlaydigan asosiy rastr formati qaysi? <ul><li><em>Javob:</em> PNG (va PSD).</li></ul></li><li>Photoshopda har bir ob&#39;ektni alohida tahrirlash imkonini beruvchi eng muhim panel qaysi? <ul><li><em>Javob:</em> Qatlamlar (Layers) paneli.</li></ul></li></ol><hr>",2))]),i("div",p,[i("h2",v,[l(r,{name:"house"}),a[12]||(a[12]=o(" Uyga vazifa ",-1)),a[13]||(a[13]=i("a",{class:"header-anchor",href:"#uyga-vazifa","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa"'},"​",-1))]),a[14]||(a[14]=i("p",null,"Daftaringizda:",-1)),a[15]||(a[15]=i("ol",null,[i("li",null,"Rastr va vektor grafikasi solishtirilgan taqqoslash jadvalini chizing (Tuzilishi, afzalligi, kamchiligi, o'yindagi o'rni va formatlari);"),i("li",null,"2D o'yin uchun 3 qatlamli parallaks fon (Background) g'oyasini tasvirlang: 1-oldingi qatlamda nima, 2-o'rta qatlamda nima, 3-uzoq orqa qatlamda nima joylashishini yozing.")],-1))])])}const I=s(d,[["render",c]]);export{D as __pageData,I as default};
